"""Build the public instrument catalogue and independent, accessible guide pages."""
import json,html,re
from pathlib import Path
root=Path(__file__).resolve().parents[1];dist=root/'dist'
items=json.loads((root/'content/instruments.json').read_text());esc=lambda x:html.escape(str(x),quote=True)
portraits={'اکبری':'akbari','جعفری':'jafari','علیرضایی':'alirezaei','کرمی':'karami','محسن اکبری':'mohsen-akbari','فروغی':'foroughi','رضایی':'rezaei'}
credits=json.loads((dist/'instrument-photos/credits.json').read_text()) if (dist/'instrument-photos/credits.json').exists() else {}
def photo(x,prefix=''):
 return prefix+'instrument-photos/'+x.get('imageKey',x['slug'])+'.webp'
def card(x,prefix=''):
 return f'''<a class="instrument-card" href="{prefix}instruments/{x['slug']}.html" style="--tone:{x['accent']};--wash:{x['tint']}" data-family="{esc(x['family'])}" data-name="{esc(x['name'])}"><div class="instrument-card-art"><img src="{photo(x,prefix)}" alt="عکس {esc(x['name'])} بدون پس‌زمینه" loading="lazy" width="480" height="420"></div><div class="instrument-card-body"><span class="instrument-family">{esc(x['family'])}</span><h3>{esc(x['name'])}</h3><p>{esc(x['tag'])}</p><span class="instrument-card-link">این ساز را بشناس <b aria-hidden="true">↖</b></span></div></a>'''
for i,x in enumerate(items):
 name=esc(x['name']);teachers=''.join(f'''<a class="master-profile" href="../index.html#masters">{f'<img src="../teachers/{portraits[t]}.webp" alt="استاد {esc(t)}" loading="lazy">' if t in portraits else '<span class="master-monogram" aria-hidden="true">'+esc(t[0])+'</span>'}<span><small>مدرس {name}</small><strong>استاد {esc(t)}</strong>{'<em>مدیر آموزشگاه و مدرس</em>' if t=='اکبری' else ''}</span><b aria-hidden="true">↖</b></a>''' for t in x['teachers']) or '<p>این ساز در برنامهٔ هفتگی آمده است. برای نام مدرس و زمان فعال کلاس، با دفتر هماهنگ کن.</p>'
 facts=''.join(f'<div><dt>{esc(a)}</dt><dd>{esc(b)}</dd></div>' for a,b in x['facts']);learn=''.join(f'<li><span>{str(n+1).translate(str.maketrans("0123456789","۰۱۲۳۴۵۶۷۸۹"))}</span>{esc(t)}</li>' for n,t in enumerate(x['learn']));faq=''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in x['faq'])
 related=[a for a in items if a['slug']!=x['slug'] and a['family']==x['family']][:3]
 if len(related)<3:related += [a for a in items if a['slug']!=x['slug'] and a not in related][:3-len(related)]
 c=credits.get(x.get('imageKey',x['slug']),{});credit=f'''<p class="photo-credit">عکس: {esc(c.get('author',''))} · <a href="{esc(c.get('source','../photo-credits.html'))}" target="_blank" rel="noopener">تصویر اصلی</a> · <a href="{esc(c.get('license_url','../photo-credits.html'))}" target="_blank" rel="noopener">{esc(c.get('license','منبع عکس'))}</a> · نسخهٔ بهینه‌شده و بدون پس‌زمینه.</p>'''
 page=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="{x['tint']}"><title>{name} | راهنمای ساز و کلاس در آوای هزاردستان</title><meta name="description" content="{esc(x['intro'][:155])}"><link rel="canonical" href="https://avayehezardastan.com/instruments/{x['slug']}.html"><link rel="icon" href="../logo.png"><link rel="stylesheet" href="../fonts.css"><link rel="stylesheet" href="../instrument-library.css"></head><body class="instrument-page" data-instrument="{x['slug']}" data-family="{esc(x['family'])}" style="--tone:{x['accent']};--wash:{x['tint']}"><header class="instrument-header"><a class="instrument-brand" href="../index.html"><img src="../logo.png" alt="آوای هزاردستان"><span>آوای هزاردستان<small>خانهٔ موسیقی و هنر</small></span></a><a class="back-library" href="../index.html#instruments">همهٔ سازها <span aria-hidden="true">←</span></a></header><main><nav class="instrument-breadcrumb" aria-label="مسیر صفحه"><a href="../index.html">خانه</a><span>/</span><a href="../index.html#instruments">جهان سازها</a><span>/</span><span aria-current="page">{name}</span></nav><section class="instrument-intro"><div class="instrument-hero-copy"><span class="instrument-eyebrow">دفتر آشنایی با سازها · {esc(x['family'])}</span><h1>{name}</h1><p class="instrument-tagline">{esc(x['tag'])}</p><p>{esc(x['intro'])}</p><div class="instrument-actions"><a class="instrument-primary" href="#instrument-teachers">استاد و مسیر کلاس <span>↙</span></a><a href="#instrument-story">بیشتر بشناس ↓</a></div><dl class="instrument-facts">{facts}</dl></div><figure class="instrument-hero-art"><div class="instrument-arch" aria-hidden="true"></div><span class="instrument-orbit" aria-hidden="true">✦</span><img src="{photo(x,'../')}" alt="عکس واقعی {name}؛ نمای کامل ساز" width="900" height="1000" fetchpriority="high"><figcaption>{name} <span>جنس صدا، سبک تو</span></figcaption></figure></section><nav class="instrument-jumps" aria-label="بخش‌های راهنمای ساز"><a href="#instrument-story">شخصیت صدا</a><a href="#instrument-learning">مسیر یادگیری</a><a href="#instrument-practice">تمرین و خرید</a><a href="#instrument-teachers">استادهای ساز</a><a href="#instrument-faq">پرسش‌ها</a></nav><section class="instrument-story" id="instrument-story"><div><span class="instrument-eyebrow">از صدا شروع کن</span><h2>صدای {name}،<br>چه دنیایی دارد؟</h2><p>{esc(x['sound'])}</p><p class="instrument-note">انتخاب ساز از علاقه و تجربه آغاز می‌شود. برای تصمیم نهایی، ساز را از نزدیک امتحان کن و با مدرس دربارهٔ شرایط تمرینت حرف بزن.</p></div><figure class="instrument-detail-photo"><img src="{photo(x,'../')}" alt="نگاه نزدیک‌تر به شکل و ساختار {name}" loading="lazy"><figcaption>نگاه نزدیک‌تر به ساز · برش از عکس اصلی</figcaption></figure></section><section class="instrument-learning" id="instrument-learning"><div><span class="instrument-eyebrow">قدم‌های نخست</span><h2>در شروع مسیر چه یاد می‌گیری؟</h2><p>ترتیب و سرعت آموزش با تجربه، تمرین و برنامهٔ استاد تنظیم می‌شود.</p></div><ol>{learn}</ol></section><section class="instrument-advice" id="instrument-practice"><article><span class="instrument-eyebrow">در خانه</span><h2>جایی برای تمرین</h2><p>{esc(x['practice'])}</p></article><article><span class="instrument-eyebrow">پیش از خرید</span><h2>آگاهانه انتخاب کن</h2><p>{esc(x['buy'])}</p><strong>پیش از خرید ساز، نظر استاد را بپرس.</strong></article></section><section class="instrument-teachers" id="instrument-teachers"><div><span class="instrument-eyebrow">یادگیری با راهنما</span><h2>همراه تو در کلاس {name}</h2><div class="instrument-masters">{teachers}</div></div><aside class="instrument-class-info"><span>کلاس در آوای هزاردستان</span><h3>یک قدم، هر هفته</h3><dl><div><dt>مدت هر جلسه</dt><dd>۲۰ دقیقه</dd></div><div><dt>هر ترم</dt><dd>۴ جلسه · هفته‌ای یک جلسه</dd></div><div><dt>شهریه هر جلسه</dt><dd>۵۰۰ هزار تومان</dd></div><div><dt>شهریه ترم</dt><dd>۲ میلیون تومان</dd></div></dl><p>شهریهٔ ترم پیش از شروع کلاس پرداخت می‌شود. ساعت ثابت و ظرفیت کلاس را با دفتر هماهنگ کن.</p><a class="instrument-primary" href="../index.html#contact">هماهنگی با آموزشگاه ↖</a></aside></section><section class="instrument-faq" id="instrument-faq"><span class="instrument-eyebrow">پیش از انتخاب</span><h2>پرسش‌های تو دربارهٔ {name}</h2>{faq}</section><section class="instrument-related"><div class="instrument-related-heading"><h2>این صداها را هم بشناس</h2><a href="../index.html#instruments">همهٔ سازها ←</a></div><div class="instrument-related-grid">{''.join(card(a,'../') for a in related)}</div></section><section class="instrument-endnote"><h2>هنوز انتخابت قطعی نیست؟</h2><p>با هزارآوا علاقه‌هایت را مرور کن و تجربهٔ ریتم و شنوایی را امتحان کن.</p><a class="instrument-primary" href="../index.html#discover">آشنایی با هزارآوا ✦</a></section>{credit}</main><footer class="instrument-footer"><a href="../index.html">آوای هزاردستان</a><a href="../photo-credits.html">منابع عکس‌ها</a><a href="../portal.html">ورود به پرتال</a></footer></body></html>'''
 (dist/'instruments'/f"{x['slug']}.html").write_text(page)
section='''<section class="instrument-library" id="instruments" aria-labelledby="sound-heading"><div class="instrument-library-heading"><div><span class="instrument-eyebrow">جهان سازهای هزاردستان</span><h2 id="sound-heading">هر ساز، <em>یک جهان تازه.</em></h2><p>از جنس صدا تا اولین تمرین؛ سازت را بشناس و استاد مسیرت را پیدا کن.</p></div><span class="instrument-total">۲۱ مسیر برای کشف</span></div><div class="instrument-filterbar"><label class="instrument-search"><span aria-hidden="true">⌕</span><input type="search" id="instrument-search" placeholder="کدام ساز را می‌خواهی بشناسی؟" aria-label="جست‌وجوی ساز"></label><div class="instrument-filters" role="group" aria-label="خانواده سازها"><button aria-pressed="true" data-filter="all">همهٔ سازها</button>'''+''.join(f'<button aria-pressed="false" data-filter="{esc(f)}">{esc(f)}</button>' for f in dict.fromkeys(x['family'] for x in items))+'''</div></div><p class="instrument-results" id="instrument-results" aria-live="polite">۲۱ ساز و مسیر آموزشی</p><div class="instrument-grid">'''+''.join(card(x) for x in items)+'''</div><p id="instrument-empty" hidden>سازی با این نام پیدا نشد. نام کوتاه‌تری بنویس یا خانوادهٔ دیگری را انتخاب کن.</p><div class="instrument-library-footer"><p>آواز، سلفژ، آهنگسازی و تنظیم، دی‌جی و هنرهای تجسمی را در <a href="#courses">رشته‌های آموزشی</a> ببین.</p><button class="discover-trigger" type="button">با هزارآوا مسیرم را پیدا کنم ✦</button></div></section>'''
s=(dist/'index.html').read_text();a=s.index('<section class="sound-hero') if '<section class="sound-hero' in s else s.index('<section class="instrument-library"');b=s.index('</section>',a)+10;s=s[:a]+section+s[b:];s=s.replace('<link rel="stylesheet" href="instrument-library.css">','');s=s.replace('<link rel="stylesheet" href="courtyard.css">','<link rel="stylesheet" href="courtyard.css"><link rel="stylesheet" href="instrument-library.css">');s=re.sub(r'<dialog id="sound-detail".*?</dialog>','',s);s=s.replace('<script src="sound-explorer.js"></script>','<script src="instrument-library.js"></script>');s=s.replace('<section class="hava-showcase">','<section class="hava-showcase" id="discover">');(dist/'index.html').write_text(s)
print(f'Generated {len(items)} pages and catalogue')
